mapper.select:
select m.*, p.status AS participantStatus,
CASE WHEN f.favorite_id IS 
NULL THEN 0 ELSE 1 END AS favorite
from team_match_participant p
join team_match m 
on m.team_match_id = p.team_match_id
LEFT JOIN favorite f
on f.match_id = m.team_match_id
AND f.user_id = #{userId}
AND f.match_type = 'Team'
WHERE p.user_id = #{userId}
AND p.status IN ('결제완료')

	AND m.sport = #{sport}


	AND m.status = #{status}

 AND m.match_date >= #{startDate} 
 AND m.match_date <= #{endDate} 
ORDER BY m.match_date, m.team_match_id
LIMIT #{size} OFFSET
#{offset}

SELECT COUNT(*) FROM team_match_participant p JOIN team_match m ON m.team_match_id = p.team_match_id WHERE p.user_id = #{userId} AND p.status IN ('결제완료')
AND m.match_date >= STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d') AND m.match_date < DATE_ADD(STR_TO_DATE(CONCAT(#{month}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
AND m.sport = #{sport}
AND m.status = #{status}

SELECT DISTINCT DATE_FORMAT(m.match_date, '%Y-%m-%d')
FROM team_match_participant p
JOIN team_match m
ON m.team_match_id = p.team_match_id
WHERE p.user_id = #{userId}
AND p.status IN ('결제완료')

	AND m.sport = #{sport}


	AND m.status = #{status}
